    if type(dc) is not list or len(dc) != Tq:
        raise ValueError("dc must be a list of shape %d×%d" % (Tq, Dv))
    for row in dc:
        if type(row) is not list or len(row) != Dv:
            raise ValueError("dc must be a list of shape %d×%d" % (Tq, Dv))
